// Generated by OrchestKit Claude Plugin
// Created: 2026-07-24

/**
 * Executor Route Nudge — UserPromptSubmit sub-hook (prompt/unified-dispatcher)
 *
 * M170/#3127: skill telemetry showed think skills (brainstorm/auto/assess)
 * running 141x per 30d while executor skills (implement/cover/fix-issue/
 * review-pr/verify) ran 6x — yet build work clearly ships daily. Build-shaped
 * goals are handled inline in the main loop, so the specialist wiring the
 * executors carry (implement -> 27 architect refs, cover -> test-generator)
 * never activates. Funnel tracing found ZERO auto->executor transitions
 * across 43 observed hand-offs.
 *
 * This sub-hook fires AT MOST ONCE PER SESSION: when a prompt is build-shaped
 * (imperative build/fix verb, goal-length, no explicit skill invocation), it
 * injects a one-line reminder that the executor skills exist and carry the
 * specialist wiring. Advisory context only — never blocks, never rewrites.
 *
 * Runs inside prompt/unified-dispatcher (no separate hooks.json entry).
 *
 * @see https://github.com/yonatangross/orchestkit/issues/3127
 */

import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { HookContext, HookInput, HookResult } from '../types.js';
import { outputPromptContext, outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { getSessionStorageDir } from '../lib/paths.js';

const HOOK_NAME = 'executor-route-nudge';

/** Prompts shorter than this are commands/answers, not goal statements. */
const MIN_GOAL_LENGTH = 40;

/** Imperative build/fix openers — mirror of ork:auto's build+fix categories. */
const BUILD_VERB_RE =
  /^(?:please\s+|can you\s+|let'?s\s+)?(?:fix|debug|build|implement|create|add|scaffold|set up|refactor)\b/i;

/** The user is already routing — do not second-guess an explicit invocation. */
const ALREADY_ROUTED_RE = /\/(?:ork|hq-ext):[a-z-]+/i;

function flagPath(sessionId: string): string {
  return join(getSessionStorageDir(), `${sessionId}-executor-nudge.flag`);
}

export function executorRouteNudge(
  input: HookInput,
  _ctx: HookContext = NOOP_CTX,
): HookResult {
  const prompt = typeof input.prompt === 'string' ? input.prompt : '';
  const sessionId = input.session_id || 'unknown-session';

  if (prompt.length < MIN_GOAL_LENGTH) return outputSilentSuccess();
  if (!BUILD_VERB_RE.test(prompt.trim())) return outputSilentSuccess();
  if (ALREADY_ROUTED_RE.test(prompt)) return outputSilentSuccess();

  // Once per session: a standing reminder would be noise, one is signal.
  const flag = flagPath(sessionId);
  try {
    if (existsSync(flag)) return outputSilentSuccess();
    mkdirSync(getSessionStorageDir(), { recursive: true });
    writeFileSync(flag, new Date().toISOString(), 'utf-8');
  } catch {
    // Flag I/O failure: prefer silence over risking a nudge every turn.
    return outputSilentSuccess();
  }

  return outputPromptContext(
    `[${HOOK_NAME}] Build-shaped goal detected. The executor skills carry the specialist wiring ` +
      `(/ork:implement, /ork:fix-issue, /ork:cover) — invoke one via the Skill tool or route through ` +
      `/ork:auto instead of building inline in the main loop. One-time reminder this session (M170).`,
  );
}
